#!/usr/bin/env bash
# Shared pieces of the Linux/macOS release flow (sourced by tools/make_installer_unix.sh and the two
# package_*.sh scripts). It mirrors what tools/make_installer.sh does on Windows, step for step, so a
# release is "run tools/make_installer.sh" on every OS:
#
#   version   one source of truth: kAppVersion in qml/services/SettingsService.cpp (never passed by hand)
#   seed      design catalogs GENERATED by the engine (bps_cli --dump-catalogs), plus this machine's
#             configuration snapshot (tools/make_seed_config.mjs) — a catalog is never hand-copied
#   verdict   "INSTALLER: PASS" / "INSTALLER: FAIL <stage>", exit 0 / 1, the same lines the Windows
#             script prints, so one CI grep reads all three

# ---- progress ------------------------------------------------------------------------------------
# So a long release is never a silent terminal: every stage announces itself as [n/N] with the time
# since the run began, long silent tools (downloads, macdeployqt, linuxdeploy, hdiutil) print a
# heartbeat line with their elapsed time, and a stage's end prints how long it took.
RELEASE_T0="${RELEASE_T0:-$SECONDS}"
RELEASE_STAGE_TOTAL="${RELEASE_STAGE_TOTAL:-0}"
RELEASE_STAGE_N="${RELEASE_STAGE_N:-0}"
RELEASE_STAGE_T="$SECONDS"

fmt_elapsed() {   # <seconds> -> 1m07s
    local s="$1"
    if [ "$s" -ge 60 ]; then printf '%dm%02ds' "$((s / 60))" "$((s % 60))"; else printf '%ds' "$s"; fi
}

stage_begin() {   # <title>  (RELEASE_STAGE_TOTAL is how many stages this run has)
    RELEASE_STAGE_N=$((RELEASE_STAGE_N + 1)); export RELEASE_STAGE_N
    RELEASE_STAGE_T="$SECONDS"
    echo
    echo "[$RELEASE_STAGE_N/$RELEASE_STAGE_TOTAL] $1   (elapsed $(fmt_elapsed $((SECONDS - RELEASE_T0))))"
}

stage_done() {    # [detail]
    echo "    done in $(fmt_elapsed $((SECONDS - RELEASE_STAGE_T)))${1:+ — $1}"
}

step() { echo "    · $*"; }   # a sub-step inside a stage (packaging is a handful of them)

# Run a command that prints nothing for a long time, with a "still working" line every 15 s.
# Exit status is the command's own. Output (stdout/stderr) is untouched.
with_heartbeat() {   # <label> <cmd...>
    local label="$1" t0="$SECONDS" hb rc=0
    shift
    ( while sleep 15; do echo "    … $label — still working ($(fmt_elapsed $((SECONDS - t0))))"; done ) &
    hb=$!
    "$@" || rc=$?
    kill "$hb" 2>/dev/null || true
    wait "$hb" 2>/dev/null || true
    return "$rc"
}

# ---- verdict -------------------------------------------------------------------------------------
installer_fail() {
    echo; echo "failed after $(fmt_elapsed $((SECONDS - RELEASE_T0)))"
    echo "INSTALLER: FAIL $1"   # exactly the Windows script's verdict line
    exit 1
}

# ---- version ---------------------------------------------------------------------------------------
# Identical to the Windows script's extraction, so the two can never disagree about the version.
release_version() {
    local root="$1"
    grep -oE 'kAppVersion = "[^"]+"' "$root/qml/services/SettingsService.cpp" \
        | head -1 | sed -E 's/.*"([^"]+)"/\1/'
}

# ---- the artifact's name -----------------------------------------------------------------------------
# VGRPresenter-Setup-<version>.exe on Windows; here: VGRPresenter-Setup-<version>-<os>-<arch>.<ext>
release_artifact() {   # <out-dir> <version> <os: linux|macos> <ext>
    echo "$1/VGRPresenter-Setup-$2-$3-$(uname -m).$4"
}

# ---- Qt ----------------------------------------------------------------------------------------------
find_qt_prefix() {
    if [ -n "${QT_ROOT_DIR:-}" ]; then echo "$QT_ROOT_DIR"; return 0; fi
    local q
    for q in qmake6 qmake; do
        if command -v "$q" >/dev/null 2>&1; then "$q" -query QT_INSTALL_PREFIX; return 0; fi
    done
    local d
    for d in "$HOME"/Qt/6.11.*/gcc_64 "$HOME"/Qt/6.11.*/macos /opt/Qt/6.11.*/gcc_64; do
        if [ -d "$d" ]; then echo "$d"; return 0; fi
    done
    return 1
}

# ---- seed: catalogs from the engine ---------------------------------------------------------------------
# bps_cli links the engine; run on the clean data dir it dumps the shipped design catalogs.
seed_catalogs() {   # <root> <bps_cli>
    local root="$1" cli="$2"
    local seed="$root/installer/seed-data" run="$root/build/.seed-dump"
    [ -x "$cli" ] || { echo "bps_cli not found at $cli — cannot generate the shipped catalogs"; return 1; }
    rm -rf "$run"; mkdir -p "$run" "$seed/local"
    step "generating the design catalogs from the engine (bps_cli --dump-catalogs)"
    if ! ( cd "$run" && "$cli" --data "$run/data" --dump-catalogs "$seed/local" ); then
        rm -rf "$run"; echo "catalog dump FAILED"; return 1
    fi
    rm -rf "$run"
    step "catalogs written: $(find "$seed/local" -type f 2>/dev/null | wc -l | tr -d ' ') files"
}

# ---- seed: this machine's configuration -------------------------------------------------------------------
# The same snapshot the Windows installer takes, from wherever THIS OS keeps the files: the checkout's
# dev-profile when there is one (a development build runs against it), else the per-user locations the
# app itself uses. Nothing to snapshot (a clean build machine) is not an error: the package then ships
# the catalogs and the engine's own defaults.
seed_config() {   # <root> <exe-dir the app runs from: assets/settings.shipped.json lands beside it>
    local root="$1" exe_dir="$2" settings kernel data_home app_data
    if [ "$(uname -s)" = "Darwin" ]; then
        data_home="$HOME/Library/Application Support"; app_data="$data_home/VGR/VGRPresenter"
    else
        data_home="${XDG_DATA_HOME:-$HOME/.local/share}"; app_data="$data_home/VGR/VGRPresenter"
    fi
    settings="${BPS_SETTINGS_FILE:-}"
    kernel="${BPS_KERNEL_FILE:-}"
    if [ -z "$settings" ]; then
        if [ -f "$root/dev-profile/local/settings.json" ]; then settings="$root/dev-profile/local/settings.json"
        elif [ -f "$data_home/bps/settings.json" ]; then settings="$data_home/bps/settings.json"; fi
    fi
    if [ -z "$kernel" ]; then
        if [ -f "$root/dev-profile/roaming/enginedata/kernel.json" ]; then kernel="$root/dev-profile/roaming/enginedata/kernel.json"
        elif [ -f "$app_data/enginedata/kernel.json" ]; then kernel="$app_data/enginedata/kernel.json"; fi
    fi
    if [ -z "$settings" ]; then
        step "no settings.json on this machine — shipping the engine's defaults (no configuration snapshot)"
        return 0
    fi
    step "bundling this machine's configuration (settings + kernel)"
    mkdir -p "$exe_dir/assets"
    BPS_SETTINGS_FILE="$settings" BPS_KERNEL_FILE="${kernel:-/nonexistent/kernel.json}" \
    BPS_DIST_DIR="$exe_dir" "${NODE_BIN:-node}" "$root/tools/make_seed_config.mjs"
}
